function unsortedColumns(strs: string[]): number {
  let count = 0;
  for (let c = 0; c < strs[0].length; c++) {
    const col = strs.map(s => s[c]);
    if (col.join("") !== [...col].sort().join("")) count++;
  }
  return count;
}

