function unsortedColumns(strs: string[]): number {
  let count = 0;
  for (let c = 0; c < strs[0].length; c++) {
    for (let i = 0; i + 1 < strs.length; i++) {
      if (strs[i][c] > strs[i + 1][c]) { count++; break; }
    }
  }
  return count;
}

